    A recursive descent parser that processes a JSON string and converts it
    to corresponding Python data structures like dict, list, str, int/float, 
    bool, and None. The function handles strings, numbers, booleans, null,
    arrays, and objects by using state management to navigate the different
    elements in a JSON structure.
    """

    class JsonParser:
        def __init__(self, s):
            self.s = s
            self.index = 0

        def skip_whitespace(self):
            while self.index < len(self.s) and self.s[self.index].isspace():
                self.index += 1

        def parse_value(self):
            self.skip_whitespace()
            if self.index >= len(self.s):
                raise ValueError("Unexpected end of input")
            char = self.s[self.index]

            if char == '"':
                return self.parse_string()
            elif char.isdigit() or char == '-':
                return self.parse_number()
            elif self.s.startswith("true", self.index):
                self.index += 4
                return True
            elif self.s.startswith("false", self.index):
                self.index += 5
                return False
            elif self.s.startswith("null", self.index):
                self.index += 4
                return None
            elif char == '[':
                return self.parse_array()
            elif char == '{':
                return self.parse_object()
            else:
                raise ValueError(f"Unexpected character: {char}")

        def parse_string(self):
            self.index += 1  # Skip opening quote
            start = self.index
            result = []
            while self.index < len(self.s):
                char = self.s[self.index]
                if char == '"':
                    result.append(self.s[start:self.index])
                    self.index += 1  # Skip closing quote
                    return ''.join(result)
                elif char == '\\':
                    if self.index + 1 < len(self.s):
                        self.index += 1  # Skip backslash
                        next_char = self.s[self.index]
                        if next_char in '"\\/bfnrt':
                            result.append({'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 
                                           'n': '\n', 'r': '\r', 't': '\t'}[next_char])
                            self.index += 1
                        else:
                            raise ValueError(f"Invalid escape sequence: \\{next_char}")
                    else:
                        raise ValueError("Unterminated string")
                else:
                    result.append(char)
                    self.index += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
